def is_not_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return False
    if n % 2 == 0:
        return True

    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(numbers, n):
    if n <= 0:
        return []
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(a, b):
    x = abs(a) ^ abs(b)
    return x != 0 and (x & (x - 1)) == 0

