import re

def find_char_long(text):
    return re.findall(r"\b\w{4,}\b", text)

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0

    doubled = s + s
    for i in range(1, n + 1):
        if doubled[i:i + n] == s:
            return i

    return n

def remove_Occ(s, c):
    first = s.find(c)
    if first == -1:
        return s

    last = s.rfind(c)

    if first == last:
        return s[:first] + s[first + 1:]

    return s[:first] + s[first + 1:last] + s[last + 1:]

import re

def text_lowercase_underscore(text):
    if not isinstance(text, str) or not text:
        return False
    return re.fullmatch(r"[a-z]+_[a-z]+", text) is not None

def remove_dirty_chars(string, chars):
    remove_set = set(chars)
    return ''.join(ch for ch in string if ch not in remove_set)

def is_woodall(num):
    if not isinstance(num, int) or isinstance(num, bool):
        return False

    if num <= 0:
        return False

    n = 1
    target = num + 1

    while n * (1 << n) <= target:
        if n * (1 << n) == target:
            return True
        n += 1

    return False

def find_Max_Num(nums):
    if not nums:
        return 0
    return int(''.join(map(str, sorted(nums, reverse=True))))

