def is_octagonal(n):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 0:
        raise ValueError("n must be a positive integer")
    return n * (3 * n - 2)

def count_Substrings(s):
    count = 0
    prefix_sum = 0
    prefix_counts = {0: 1}

    for ch in s:
        prefix_sum += int(ch) - 1
        count += prefix_counts.get(prefix_sum, 0)
        prefix_counts[prefix_sum] = prefix_counts.get(prefix_sum, 0) + 1

    return count

def max_difference(tuple_list):
    if not tuple_list:
        return None
    return max(abs(a - b) for a, b in tuple_list)

def recursive_list_sum(data_list):
    total = 0
    for item in data_list:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def bell_number(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    bell = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    bell[0][0] = 1

    for i in range(1, n + 1):
        bell[i][0] = bell[i - 1][i - 1]
        for j in range(1, i + 1):
            bell[i][j] = bell[i - 1][j - 1] + bell[i][j - 1]

    return bell[n][0]

def is_Monotonic(arr):
    return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)) or all(
        arr[i] >= arr[i + 1] for i in range(len(arr) - 1)
    )

def is_sublist(list1, list2):
    if not list2:
        return True
    if not list1 or len(list2) > len(list1):
        return False

    sub_len = len(list2)
    for i in range(len(list1) - sub_len + 1):
        if list1[i:i + sub_len] == list2:
            return True
    return False

def get_equal(tuples_list):
    if not isinstance(tuples_list, list):
        raise TypeError("Input must be a list of tuples")

    if not tuples_list:
        return True

    expected_length = len(tuples_list[0])
    return all(len(t) == expected_length for t in tuples_list)

def comb_sort(elements):
    arr = list(elements)
    gap = len(arr)
    shrink = 1.3
    swapped = True

    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1

        swapped = False
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

def is_diff_of_two(n):
    return n % 2 != 0 or n % 4 == 0


def dif_Square(n):
    return is_diff_of_two(n)

def is_samepatterns(patterns1, patterns2):
    if len(patterns1) != len(patterns2):
        return False

    map_1_to_2 = {}
    map_2_to_1 = {}

    for item1, item2 in zip(patterns1, patterns2):
        if item1 in map_1_to_2:
            if map_1_to_2[item1] != item2:
                return False
        else:
            map_1_to_2[item1] = item2

        if item2 in map_2_to_1:
            if map_2_to_1[item2] != item1:
                return False
        else:
            map_2_to_1[item2] = item1

    return True

def find_tuples(tuples, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k == 0:
        raise ValueError("k must not be zero")
    return [tup for tup in tuples if all(element % k == 0 for element in tup)]

def tetrahedral_number(n):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return n * (n + 1) * (n + 2) // 6

def sequence(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n <= 2:
        return 1

    a = [0] * (n + 1)
    a[1] = a[2] = 1

    for i in range(3, n + 1):
        a[i] = a[a[i - 1]] + a[i - a[i - 1]]

    return a[n]

import math

def surfacearea_sphere(radius):
    if radius < 0:
        raise ValueError("Radius must be non-negative")
    return 4 * math.pi * radius ** 2

