def freq_count(data):
    counts = {}
    for element in data:
        counts[element] = counts.get(element, 0) + 1
    return counts

def is_undulating(n):
    s = str(n)

    if s.startswith("-"):
        return False

    if len(s) < 3:
        return False

    if s[0] == s[1]:
        return False

    return all(s[i] == s[i - 2] for i in range(2, len(s)))

def index_minimum(tuples_list):
    if not isinstance(tuples_list, list):
        raise TypeError("Input must be a list of tuples")

    if not tuples_list:
        return None

    min_tuple = None

    for item in tuples_list:
        if not isinstance(item, tuple):
            raise TypeError("All elements must be tuples")
        if len(item) < 2:
            raise ValueError("Each tuple must contain at least two elements")

        if min_tuple is None or item[1] < min_tuple[1]:
            min_tuple = item

    return min_tuple[0]

def Find_Min_Length(list_of_lists):
    if not list_of_lists:
        return 0
    return min(len(sublist) for sublist in list_of_lists)

def divisor(n):
    n = abs(n)
    if n == 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
        i += 1

    return count

def frequency_lists(list_of_lists):
    frequencies = {}
    for sublist in list_of_lists:
        for element in sublist:
            frequencies[element] = frequencies.get(element, 0) + 1
    return frequencies

def multiply_num(numbers):
    if not numbers:
        return 0.0

    product = 1
    for num in numbers:
        product *= num

    return product / len(numbers)

def decimal_to_binary(n):
    if n == 0:
        return "0"
    if n < 0:
        return "-" + decimal_to_binary(-n)
    return bin(n)[2:]

def next_smallest_palindrome(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    target = n + 1
    s = str(target)

    def mirror_from_left(num_str):
        length = len(num_str)
        half = (length + 1) // 2
        left = num_str[:half]
        if length % 2 == 0:
            return int(left + left[::-1])
        return int(left + left[:-1][::-1])

    palindrome = mirror_from_left(s)
    if palindrome >= target:
        return palindrome

    length = len(s)
    half = (length + 1) // 2
    left = str(int(s[:half]) + 1)

    if length % 2 == 0:
        return int(left + left[::-1])
    return int(left + left[:-1][::-1])

