def tuple_to_int(values):
    if values is None or not isinstance(values, tuple) or len(values) == 0:
        raise TypeError("Input must be a non-empty tuple of positive integers")

    for value in values:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("All elements must be integers")
        if value <= 0:
            raise ValueError("All elements must be positive integers")

    return int("".join(str(value) for value in values))

def search(arr):
    i = 0
    n = len(arr)

    while i < n:
        j = i + 1
        while j < n and arr[j] == arr[i]:
            j += 1

        if j - i == 1:
            return arr[i]

        i = j

    return None

def max_product_tuple(tuple_list):
