import math

def _sum_proper_divisors(n):
    if n <= 1:
        return 0

    total = 1
    limit = math.isqrt(n)

    for d in range(2, limit + 1):
        if n % d == 0:
            total += d
            other = n // d
            if other != d:
                total += other

    return total

def amicable_numbers_sum(n):
    total = 0

    for num in range(2, n + 1):
        partner = _sum_proper_divisors(num)
        if partner != num and _sum_proper_divisors(partner) == num:
            total += num

    return total

import cmath

def angle_complex(real, imag=None):
    if imag is None:
        z = complex(real)
    else:
        if isinstance(imag, complex) and imag.imag != 0:
            z = complex(real) + imag
        else:
            z = complex(real, imag)
    return cmath.phase(z)

def find_length(string):
    if not string:
        return 0

    max_diff = float("-inf")
    current_diff = 0

    for char in string:
        value = 1 if char == "0" else -1
        current_diff = max(value, current_diff + value)
        max_diff = max(max_diff, current_diff)

    return max_diff

import math

def sum(a, b):
    g = math.gcd(abs(a), abs(b))
    if g == 0:
        return 0

    total = 0
    for i in range(1, int(g ** 0.5) + 1):
        if g % i == 0:
            total += i
            other = g // i
            if other != i:
                total += other

    return total

def long_words(n, words):
    if isinstance(words, str):
        words = words.split()
    return [word for word in words if len(word) > n]

def magic_square_test(matrix):
    if not isinstance(matrix, (list, tuple)) or not matrix:
        return False

    n = len(matrix)
    numbers = []

    for row in matrix:
        if not isinstance(row, (list, tuple)) or len(row) != n:
            return False

        for value in row:
            if type(value) is not int:
                return False
            numbers.append(value)

    if set(numbers) != set(range(1, n * n + 1)):
        return False

    magic_sum = n * (n * n + 1) // 2

    for row in matrix:
        if sum(row) != magic_sum:
            return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    return True
